// 正向只接真实攻城/政治批准银行；税政参数取实际页面，不注入钱粮、权源或胜负。
#define main original_disruption_helpers_main
#include "production_disruption_live_probe.cpp"
#undef main
namespace {
const StableId fiscal_site="qingxi::place.south.camp";
V normal_tax(ResidentReplaySession& world){const auto bank=need(world.checkpoint(),"before fiscal policy page");auto page=query(world,"political_occupation_fiscal",boundary::obj({{"place_id",V{fiscal_site}}}));for(const auto& row:boundary::array(field(page,"rows"),"rows"))for(const auto& action:boundary::array(field(row,"actions"),"actions"))if(text(action,"command")=="political_set_occupation_tax"&&text(field(action,"params"),"mode")=="normal"&&boundary::get_bool(action,"available","action")){check(bank==need(world.checkpoint(),"after fiscal policy page"),"policy page changed complete world");return field(action,"params");}throw std::runtime_error("real available normal occupation tax action missing");}
V tax_command(ResidentReplaySession& world,const V& params,bool preview=false){auto context=query(world,"command_context");auto envelope=boundary::obj({{"actor_id",field(context,"actor_id")},{"kind",V{"political_set_occupation_tax"}},{"params",params}});if(!preview){envelope.as<V::Dict>()->emplace_back("expected_revision",field(context,"revision"));envelope.as<V::Dict>()->emplace_back("request_seq",field(context,"next_request_seq"));}return need(world.execute_live({preview?LiveOperationKind::preview:LiveOperationKind::command,need(world.identity(),"tax command identity"),envelope}),"tax command transport").result;}
void tax_money_conserved(const V& before,const V& after){std::map<StableId,Integer> deltas;const auto& economy=field(after,"local_economy");for(const auto& payment:boundary::object(field(economy,"payments"),"payments"))if(!field(field(before,"local_economy"),"payments").find(payment.first)){const auto& p=payment.second;deltas[text(p,"from_wallet_id")]-=number(p,"amount");deltas[text(p,"to_wallet_id")]+=number(p,"amount");}const auto& taxes=field(after,"occupation_fiscal_settlement");for(const auto& payment:boundary::object(field(taxes,"payments"),"tax payments"))if(!field(field(before,"occupation_fiscal_settlement"),"payments").find(payment.first)){const auto& p=payment.second;const auto& a=field(field(field(taxes,"assessments"),text(p,"assessment_id")),"assessment");const auto& period=field(field(taxes,"periods"),text(a,"period_id"));deltas[text(a,"wallet_id")]-=number(p,"cash_paid");deltas[text(field(period,"policy"),"public_wallet_id")]+=number(p,"cash_paid");}check(!deltas.empty(),"actual settlement cash movement");for(const auto& change:deltas)check(number(field(field(after,"wallets"),change.first),"balance")-number(field(field(before,"wallets"),change.first),"balance")==change.second,"actual wage plus tax conservation "+change.first);}
V visible_tax_ledger(ResidentReplaySession& world){const auto bank=need(world.checkpoint(),"before fiscal ledger");auto economy=query(world,"local_economy",boundary::obj({{"place_id",V{fiscal_site}}}));check(boundary::get_bool(economy,"occupation_fiscal_available","economic page"),"new paired fiscal page enabled");for(const auto& authority:boundary::array(field(economy,"authorities"),"authorities")){auto page=query(world,"occupation_fiscal_settlement",boundary::obj({{"place_id",V{fiscal_site}},{"authority",authority}}));if(!boundary::array(field(page,"rows"),"rows").empty()){check(bank==need(world.checkpoint(),"after fiscal ledger"),"fiscal ledger changed complete world");return page;}}throw std::runtime_error("actual fiscal inspect account permission missing");}
}
int main(int argc,char** argv){fs::path root;try{
 check(argc==4,"usage: occupation_fiscal_live_probe CATALOG APPROVED_BANK FRESH_OUTPUT");root=argv[3];check(!fs::exists(root),"output must be new");fs::create_directories(root);const auto catalog=read(argv[1]);std::ifstream input(argv[2],std::ios::binary);check(bool(input),"read original approved bank");const Bytes approved((std::istreambuf_iterator<char>(input)),{});auto world=create_resident_replay_session();auto loaded=world->initialize_checkpoint(catalog,approved);check(loaded.ok,"actual approved world: "+loaded.error.original.code);check(approved==need(world->checkpoint(),"original bank exact"),"original bank cold drift");const auto initial=exported(*world);save(*world,root,"approved-input");
 const auto before_preview=need(world->checkpoint(),"before tax preview");auto params=normal_tax(*world);auto preview=tax_command(*world,params,true);write(root/"preview.json",preview);check(boundary::get_bool(preview,"ok","preview"),"actual tax preview denied: "+json(preview));check(before_preview==need(world->checkpoint(),"after tax preview"),"preview changed entire world");auto issued=tax_command(*world,params);trace.push_back(issued);check(boundary::get_bool(issued,"ok","issued"),"actual tax issue denied: "+json(issued));const auto signed_state=exported(*world);for(const auto* key:{"wallets","inventories","fiscal_settlement","occupation_fiscal_settlement"})check(compare_boundary(field(initial,key),field(signed_state,key)).exact(),StableId{"zero-time policy issue changed "}+key);const Integer ids=number(signed_state,"next_instance_id")-number(initial,"next_instance_id");check(ids>=2,"actual policy and result IDs recorded");save(*world,root,"signed-policy");
 const auto envelope=need(inspect_checkpoint_selected(approved,checkpoint_domains_from_identity),"actual original identity");auto prepared=need(prepare_native_catalog(catalog,"econhandover::scenario.south_production",envelope.identity.catalog),"authored 1.1 fiscal catalog");WorldBundle risk(prepared,need(decode_world_checkpoint(approved,*prepared),"late-ID decode approved"));risk.common.state().next_instance_id=INT64_MAX-ids+1;check(risk.validate().ok,"late-ID starting bank valid");auto fault=create_resident_replay_session();loaded=fault->initialize_checkpoint(catalog,need(encode_world_checkpoint(risk),"late-ID bank"));check(loaded.ok,"late-ID cold install");const auto fault_before=need(fault->checkpoint(),"late-ID before");auto rejected=tax_command(*fault,normal_tax(*fault));write(root/"late-id-rejection.json",rejected);check(!boundary::get_bool(rejected,"ok","rejection")&&text(rejected,"code")=="InstanceIdOverflow","late final result ID refused");check(fault_before==need(fault->checkpoint(),"late-ID after"),"late-ID failed whole World rollback");
 const auto& progress=boundary::object(field(field(initial,"fiscal_settlement"),"districts"),"districts");check(progress.size()==1,"single authored fiscal district");const auto due=number(progress.front().second,"next_due_tick");check(due>need(world->identity(),"issued tick").tick&&due-need(world->identity(),"issued tick").tick<=4,"original four-halfday cycle remains");while(need(world->identity(),"tax clock").tick<due){const auto tick=need(world->identity(),"before tax halfday").tick;submit(*world,"wait");if(need(world->identity(),"after wait").tick==tick)submit(*world,"advance");check(need(world->identity(),"after tax halfday").tick==tick+1,"exact original halfday");}
 const auto final=exported(*world);const auto& ledger=field(final,"occupation_fiscal_settlement");check(boundary::object(field(ledger,"periods"),"periods").size()==1&&boundary::object(field(ledger,"assessments"),"assessments").size()==1,"exact one new actual fiscal period");const auto& period=boundary::object(field(ledger,"periods"),"periods").front().second;const auto& assessment=field(boundary::object(field(ledger,"assessments"),"assessments").front().second,"assessment");check(number(period,"due_tick")==due&&number(period,"income_basis_points")==5000,"actual occupation window half-income source");const Integer expected_due=8*number(period,"tax_base_bp")*5000/100000000;check(number(assessment,"cash_remainder_before")==0&&number(field(assessment,"cash"),"original_due")==expected_due,"first successor bucket starts zero and uses actual original tax base");check(number(field(field(initial,"wallets"),text(assessment,"wallet_id")),"balance")>=expected_due,"approved author bank has actual taxpayer funding");check(number(field(assessment,"cash"),"paid_amount")==expected_due&&expected_due>0,"actual first new tax fully paid from original household funds");check(compare_boundary(field(field(initial,"fiscal_settlement"),"assessments"),field(field(final,"fiscal_settlement"),"assessments")).exact(),"legacy flow did not double assess or rewrite original debt");tax_money_conserved(initial,final);write(root/"page.json",visible_tax_ledger(*world));const auto final_bank=save(*world,root,"final");auto cold=create_resident_replay_session();loaded=cold->initialize_checkpoint(catalog,final_bank);check(loaded.ok&&final_bank==need(cold->checkpoint(),"cold final bank"),"actual new tax bank exact cold restore");
 auto duplicate=final;duplicate.find("occupation_fiscal_settlement")->as<V::Dict>()->emplace_back("version",V{Integer{1}});auto bad=decode_world_seed(duplicate,*prepared);check(!bad.ok&&bad.error.original.code=="DuplicateEconomicPayloadField","actual new fiscal duplicate JSON rejected");auto damaged=need(inspect_checkpoint_selected(final_bank,checkpoint_domains_from_identity),"actual final envelope");damaged.sections.erase(std::remove_if(damaged.sections.begin(),damaged.sections.end(),[](const auto& row){return row.domain=="occupation_fiscal_settlement";}),damaged.sections.end());auto refused=world->restore(need(encode_checkpoint(damaged),"missing new fiscal section"));check(!refused.ok&&refused.error.original.code=="CheckpointDomainMismatch"&&final_bank==need(world->checkpoint(),"after refused fiscal bank"),"missing fiscal pair section rejects atomically");write(root/"commands.json",V{trace});write(root/"result.json",boundary::obj({{"ok",V{true}},{"checks",V{checks}},{"real_world",V{true}},{"actual_cash_paid",V{expected_due}},{"main_tested",V{false}},{"gui_tested",V{false}}}));std::cout<<"actual occupation fiscal issue/first period/funds/cold/bad-bank/late-ID: "<<checks<<" checks PASS\n";return 0;
 }catch(const std::exception& error){if(!root.empty())write(root/"failure.json",boundary::obj({{"error",V{StableId{error.what()}}},{"checks",V{checks}},{"trace",V{trace}}}));std::cerr<<error.what()<<'\n';return 1;}}
